import type { TathyaConfig } from '../config.js';
import type { SuiteRun } from '../eval/types.js';
import type { TestPlan } from '../ir/types.js';

/** The frameworks `tt` can emit and run (`output.framework`, `--framework`). */
export const FRAMEWORKS = ['playwright', 'cypress'] as const;
export type Framework = (typeof FRAMEWORKS)[number];

/** First line of every generated file. */
export const GENERATED_HEADER = '// Generated by `tt generate` — do not edit; this file is overwritten on every run.\n';

/** One framework: how to write the IR as specs, and how to run them. */
export type FrameworkAdapter = { id: Framework; emitter: SpecEmitter; runner: TestRunner };

/** Renders IR test plans as TypeScript source for one framework. Pure: no I/O. */
export interface SpecEmitter {
  /** Every file of the suite (specs plus support modules), keyed by its path inside `output.dir`. */
  files(plans: TestPlan[], config: TathyaConfig): Map<string, string>;
}

/** `tt run --read-only` keeps tests tagged `@read`; `--write-only` keeps `@write`. */
export type RunMode = 'read-only' | 'write-only';

export type RunJsonOptions = {
  cwd: string;
  /** Run only these browsers (`evaluation.faultProject`); every configured browser when absent. */
  browsers?: string[];
  /** Run only the tests with these exact leaf titles (fault runs). */
  titles?: string[];
  /** Run the specs of this directory instead of `output.dir` (manual baselines). */
  testDir?: string;
  /** A framework config file shipped by a baseline directory (see `configFileName`). */
  configFile?: string;
};

/** Source-level counts of one spec file (a static proxy, not executed coverage). */
export type SpecAnalysis = {
  /** Number of test() / it() calls found in the source. */
  tests: number;
  /** Number of assertion calls found in the source. */
  assertions: number;
  /** Per-strategy locator call counts (testid/role/label/placeholder/id/name/css). */
  locatorCounts: Record<string, number>;
};

/**
 * Starts the framework and reports outcomes as `SuiteRun`. Project ids are `<role>-<browser>`;
 * a test gated to another role is reported `skipped`, never omitted (flake and kappa keys).
 */
export interface TestRunner {
  /** `tt run` / `tt all`: the framework's own console output; rejects when the run fails. */
  run(options: { configPath: string; config: TathyaConfig; args: string[]; mode?: RunMode }): Promise<void>;
  /** One evaluation run, parsed. A failing test is data: only a crash or missing report throws. */
  runJson(config: TathyaConfig, options: RunJsonOptions): Promise<SuiteRun>;
  /** `tt report`. */
  showReport(configPath: string): Promise<void>;
  /** File names of this framework's specs (baseline detection, static analysis). */
  readonly specFile: RegExp;
  /** The config file name a baseline directory may ship for itself. */
  readonly configFileName: string;
  staticAnalysis(source: string): SpecAnalysis;
}
